// merge partials from the two agents + map to STIX 2.1
// (mirror backend/osint_to_stix.py from the STIX Lab)
const domains = [...new Set(($json.body || []).map(x => x.name_value).filter(Boolean))];
const bundle = { type: 'bundle', id: 'bundle--' + $now, objects: [] };
for (const d of domains) {
  bundle.objects.push({ type: 'domain-name', value: d });
  bundle.objects.push({ type: 'indicator', pattern_type: 'stix', pattern: `[domain-name:value = '${d}']`, valid_from: new Date().toISOString(), confidence: 60 });
}
return [{ json: bundle }];

// diff vs last run stored in static data -> alert on new objects
const prev = $getWorkflowStaticData('global').lastIds || [];
const now = ($json.objects || []).map(o => o.pattern || o.value).filter(Boolean);
const added = now.filter(x => !prev.includes(x));
$getWorkflowStaticData('global').lastIds = now;
return added.length ? [{ json: { alert: 'new intelligence', added } }] : [];
